/** static void UpdateDisintegrationEffect(u8 *tiles, u16 randId, u8 c, u8 size, u8 offset) */
export function UpdateDisintegrationEffect(tiles: any, randId: any, c: any, size: any, offset: any): any {
  let heightTiles, height, widthTiles, width;
      let _var, baseOffset;
      let col, row;
      let flag, tileMask;

      height = randId / size;
      sDebug_DisintegrationData[0] = height;

      width = randId % size;
      sDebug_DisintegrationData[1] = width;

      row = height & 7;
      col = width & 7;
      sDebug_DisintegrationData[2] = height & 7;
      sDebug_DisintegrationData[3] = width & 7;

      widthTiles = width / 8;
      heightTiles = height / 8;
      sDebug_DisintegrationData[4] = width / 8;
      sDebug_DisintegrationData[5] = height / 8;

      _var = (size / 8) * (heightTiles * 64) + (widthTiles * 64);
      sDebug_DisintegrationData[6] = _var;

      baseOffset = _var + ((row * 8) + col);
      baseOffset /= 2;
      sDebug_DisintegrationData[7] = _var + ((row * 8) + col);

      flag = ((randId % 2) ^ 1);
      tileMask = (c << (flag << 2)) | 15 << (((flag ^ 1) << 2));
      tiles[baseOffset + (offset * 32)] &= tileMask;
}

